export const envelope = [17, 12, 17];

export default function build(api) {
  const [W, H, D] = api.size;
  const index = api.instance.index;
  const count = api.instance.count;
  const nextInt = (n) => Math.floor(api.random() * n);

  const ground = api.theme.ground;
  const wood = api.theme.wood;
  const stone = api.theme.stone;

  const foundationBlock = stone.primary;
  const scorchBlock = stone.accent;
  const timberLog = wood.log;
  const timberStripped = wood.stripped;
  const timberPlanks = wood.planks;

  const seat = 3;
  const fieldX = Math.floor((W - 1) / 2);
  const fieldZ = Math.floor((D - 1) / 2);
  const fieldRadius = Math.floor(Math.min(W, D) / 2);

  const rotation = (index + count + nextInt(4)) % 4;
  const centerX = fieldX + ((index + nextInt(3)) % 3) - 1;
  const centerZ = fieldZ + ((index * 2 + nextInt(3)) % 3) - 1;
  const craterRadius = 2 + ((index + nextInt(2)) % 2);
  const palisadeRadius = 5 + ((index + nextInt(2)) % 2);

  const heightSeed = nextInt(10000);
  const gapShift = (index + count + nextInt(8)) % 8;
  const debrisRoll = nextInt(10000);
  const markerRoll = nextInt(10000);
  const bannerRoll = nextInt(10000);
  const scorchSeed = nextInt(1000000);

  const put = (x, y, z, block) => {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  };

  const insideFootprint = (x, z) => {
    const dx = x - fieldX;
    const dz = z - fieldZ;
    return dx * dx + dz * dz <= fieldRadius * fieldRadius;
  };

  const isCraterCell = (x, z) => {
    const dx = x - centerX;
    const dz = z - centerZ;
    return dx * dx + dz * dz <= craterRadius * craterRadius;
  };

  const baseHeights = Array.from(
    { length: W },
    () => Array(D).fill(-1)
  );

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (!insideFootprint(x, z)) {
        continue;
      }

      let terrainOffset = Math.floor(api.heightAt(x, z));
      if (terrainOffset < -2) {
        terrainOffset = -2;
      }
      if (terrainOffset > 2) {
        terrainOffset = 2;
      }

      baseHeights[x][z] = Math.max(3, seat + terrainOffset);
    }
  }

  const surfaceY = (x, z) => {
    const base = baseHeights[x][z];
    return base + (isCraterCell(x, z) ? 0 : 1);
  };

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (!insideFootprint(x, z)) {
        continue;
      }

      const base = baseHeights[x][z];

      for (let y = 0; y < base; y++) {
        put(x, y, z, foundationBlock);
      }

      const dx = x - centerX;
      const dz = z - centerZ;
      const distanceSquared = dx * dx + dz * dz;

      if (distanceSquared <= craterRadius * craterRadius) {
        const scorchMark =
          (x * 37 + z * 61 + scorchSeed + index * 19) % 13;

        const floorMaterial =
          scorchMark < 4 || distanceSquared === 0
            ? scorchBlock
            : ground.scree;

        put(x, base, z, floorMaterial);
      } else {
        put(x, base, z, ground.revetment);

        const isRim =
          distanceSquared <= (craterRadius + 1) * (craterRadius + 1);

        const roughMark =
          (x * 19 + z * 23 + scorchSeed + index * 7) % 11;

        const outerMaterial =
          roughMark < 3 ? ground.scree : ground.pavement;

        put(
          x,
          base + 1,
          z,
          isRim ? ground.coping : outerMaterial
        );
      }
    }
  }

  const rotateOffset = (dx, dz) => {
    let rx = dx;
    let rz = dz;

    if (rotation === 1) {
      rx = -dz;
      rz = dx;
    } else if (rotation === 2) {
      rx = -dx;
      rz = -dz;
    } else if (rotation === 3) {
      rx = dz;
      rz = -dx;
    }

    return [centerX + rx, centerZ + rz];
  };

  const ringOffsets = [
    [-palisadeRadius, -2],
    [-palisadeRadius, 2],
    [-2, -palisadeRadius],
    [2, -palisadeRadius],
    [palisadeRadius, -2],
    [palisadeRadius, 2],
    [-2, palisadeRadius],
    [2, palisadeRadius]
  ];

  const bannerSlot =
    (index + bannerRoll + rotation) % ringOffsets.length;

  for (let t = 0; t < ringOffsets.length; t++) {
    if (
      t === bannerSlot ||
      (t + gapShift) % 5 === 0
    ) {
      continue;
    }

    const point = rotateOffset(
      ringOffsets[t][0],
      ringOffsets[t][1]
    );
    const sx = point[0];
    const sz = point[1];

    if (!insideFootprint(sx, sz)) {
      continue;
    }

    const stakeBase = surfaceY(sx, sz);
    let stakeHeight =
      2 + ((heightSeed + index + t * 3) % 4);

    if ((t + index + gapShift) % 7 === 0) {
      stakeHeight = 2;
    }

    for (
      let y = stakeBase + 1;
      y <= stakeBase + stakeHeight;
      y++
    ) {
      const stakeMaterial =
        y === stakeBase + stakeHeight &&
        (t + index + heightSeed) % 3 === 0
          ? timberStripped
          : timberLog;

      put(sx, y, sz, stakeMaterial);
    }
  }

  const debrisShapes = [
    [
      [-4, -2],
      [-3, -2],
      [-2, -2],
      [-2, -1]
    ],
    [
      [3, -4],
      [3, -3],
      [4, -3],
      [5, -3]
    ],
    [
      [4, 1],
      [4, 2],
      [3, 2]
    ],
    [
      [-2, 4],
      [-1, 4],
      [0, 4],
      [0, 5]
    ]
  ];

  const debrisCount =
    2 + ((index + count + debrisRoll) % 3);

  for (let c = 0; c < debrisCount; c++) {
    const shape =
      debrisShapes[
        (c + index + debrisRoll) % debrisShapes.length
      ];

    for (let j = 0; j < shape.length; j++) {
      if (
        j > 0 &&
        (j + c + index + gapShift + debrisRoll) % 7 === 0
      ) {
        continue;
      }

      const point = rotateOffset(shape[j][0], shape[j][1]);
      const x = point[0];
      const z = point[1];

      if (!insideFootprint(x, z)) {
        continue;
      }

      const debrisY = surfaceY(x, z) + 1;
      const materialChoice =
        (j + c + index + debrisRoll) % 3;

      const debrisBlock =
        materialChoice === 0
          ? timberLog
          : materialChoice === 1
            ? timberStripped
            : timberPlanks;

      put(x, debrisY, z, debrisBlock);

      if ((j + c + heightSeed) % 4 === 0) {
        put(x, debrisY + 1, z, timberPlanks);
      }
    }
  }

  const markerLength = 1 + (index % 10);
  const markerSide =
    (rotation + index + count + markerRoll) % 4;
  const markerRadius = 4;

  for (let i = 0; i < markerLength; i++) {
    const along = -4 + i;
    let mx = centerX;
    let mz = centerZ;

    if (markerSide === 0) {
      mx = centerX + along;
      mz = centerZ - markerRadius;
    } else if (markerSide === 1) {
      mx = centerX + markerRadius;
      mz = centerZ + along;
    } else if (markerSide === 2) {
      mx = centerX + along;
      mz = centerZ + markerRadius;
    } else {
      mx = centerX - markerRadius;
      mz = centerZ + along;
    }

    if (!insideFootprint(mx, mz)) {
      continue;
    }

    const markerBase = surfaceY(mx, mz);
    const markerBlock =
      (i + index + markerRoll) % 4 === 0
        ? timberLog
        : timberPlanks;

    put(mx, markerBase + 1, mz, markerBlock);

    if ((i + index + markerRoll) % 5 === 0) {
      put(mx, markerBase + 2, mz, timberStripped);
    }
  }

  const bannerOffset = ringOffsets[bannerSlot];
  const bannerPoint = rotateOffset(
    bannerOffset[0],
    bannerOffset[1]
  );
  const bx = bannerPoint[0];
  const bz = bannerPoint[1];
  const bannerBase = surfaceY(bx, bz);

  const themeId = api.theme.id.toLowerCase();
  const localIsWhite =
    themeId.indexOf("quartz") >= 0 ||
    themeId.indexOf("unicorn") >= 0 ||
    themeId.indexOf("white") >= 0;

  const opposingBanner =
    (index + count + bannerRoll) % 4 === 0;
  const bannerIsWhite = opposingBanner
    ? !localIsWhite
    : localIsWhite;

  const bannerBlock =
    "minecraft:" +
    (bannerIsWhite ? "white" : "black") +
    "_banner[rotation=" +
    ((rotation * 4 + index + bannerRoll) % 16) +
    "]";

  const poleHeight =
    4 + ((index + bannerRoll) % 2);
  const bannerY = bannerBase + poleHeight;

  for (let y = bannerBase + 1; y < bannerY; y++) {
    put(bx, y, bz, timberLog);
  }

  put(bx, bannerY, bz, bannerBlock);

  const craterFloorY = surfaceY(centerX, centerZ);

  return {
    name: "Scorched Siege Scar",
    seatY: seat,
    anchors: {
      crater: [centerX, craterFloorY + 1, centerZ],
      banner: [bx, bannerBase + 1, bz]
    }
  };
}

careened_pirate_ship.source:
export const envelope = [17, 10, 9];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const wood = api.theme.wood;
  const ground = api.theme.ground;
  const rigBlock = wood.log;

  const batch = Math.max(1, Math.floor(api.instance.count));
  const index = Math.floor(api.instance.index);
  const variant = ((index + batch) % 4 + 4) % 4;

  const r0 = api.random();
  const r1 = api.random();
  const r2 = api.random();
  const r3 = api.random();
  const r4 = api.random();
  const r5 = api.random();
  const r6 = api.random();
  const r7 = api.random();
  const r8 = api.random();
  const r9 = api.random();

  const side = (variant === 0 || variant === 2) ? 1 : -1;
  const zOffsets = [0.0, 0.16, -0.18, 0.22];

  const angle = 0.42 + r0 * 0.10 + (variant % 2) * 0.015;
  const sinA = Math.sin(angle);
  const cosA = Math.cos(angle);

  const yc = 4.25 + (r1 - 0.5) * 0.12;
  const zc = 4.5 + zOffsets[variant] + (r2 - 0.5) * 0.10;

  const uBase = 4.05 + r3 * 0.20;
  const vBase = 2.10 + r4 * 0.15;
  const taperU = 0.82 + r5 * 0.25;
  const taperV = 0.28 + r6 * 0.14;

  const damageCuts = 1 + Math.floor(r7 * 3) + (variant === 3 ? 1 : 0);
  const texturePhase = variant + Math.floor(r9 * 11);

  const restZ = side > 0 ? 1 : D - 2;
  const innerZ = restZ + side;
  const outerZ = restZ - side;

  const keelIn = side > 0 ? D - 3 : 2;
  const keelBody = side > 0 ? D - 2 : 1;
  const keelTip = side > 0 ? D - 1 : 0;

  const midX = (W - 1) / 2;
  const deckCenter = clampInt(zc + side * 0.45, 1, D - 2);

  const voxels = [];
  const locations = new Map();

  function clampInt(value, lo, hi) {
    return Math.max(lo, Math.min(hi, Math.round(value)));
  }

  function put(x, y, z, block) {
    if (
      x < 0 || x >= W ||
      y < 0 || y >= H ||
      z < 0 || z >= D ||
      block === undefined ||
      block === null
    ) {
      return;
    }

    const key = x + ":" + y + ":" + z;
    const found = locations.get(key);

    if (found === undefined) {
      locations.set(key, voxels.length);
      voxels.push([x, y, z, block]);
    } else {
      voxels[found][3] = block;
    }
  }

  function stairLine(a, b, block) {
    let x = a[0];
    let y = a[1];
    let z = a[2];

    const ax = Math.abs(b[0] - a[0]);
    const ay = Math.abs(b[1] - a[1]);
    const az = Math.abs(b[2] - a[2]);

    put(x, y, z, block);

    while (x !== b[0] || y !== b[1] || z !== b[2]) {
      let axis = -1;
      let best = -1;

      if (ax > 0) {
        const score = Math.abs(b[0] - x) / ax;
        if (score > best) {
          best = score;
          axis = 0;
        }
      }

      if (ay > 0) {
        const score = Math.abs(b[1] - y) / ay;
        if (score > best) {
          best = score;
          axis = 1;
        }
      }

      if (az > 0) {
        const score = Math.abs(b[2] - z) / az;
        if (score > best) {
          best = score;
          axis = 2;
        }
      }

      if (axis === 0) {
        x += x < b[0] ? 1 : -1;
      } else if (axis === 1) {
        y += y < b[1] ? 1 : -1;
      } else if (axis === 2) {
        z += z < b[2] ? 1 : -1;
      } else {
        break;
      }

      put(x, y, z, block);
    }
  }

  function hullPoint(x, u, v) {
    const y = yc + sinA * u + cosA * v;
    const z = zc + side * (cosA * u - sinA * v);

    return [
      x,
      clampInt(y, 0, H - 1),
      clampInt(z, 0, D - 1)
    ];
  }

  function rigTo(from, to) {
    stairLine(from, to, rigBlock);
    stairLine(to, hullPoint(to[0], 0, 0), rigBlock);
  }

  const bedZs = [outerZ, restZ, innerZ];

  for (let x = 0; x < W; x += 1) {
    for (let q = 0; q < bedZs.length; q += 1) {
      const bz = bedZs[q];
      const terrain = api.heightAt(x, bz);
      const top = Math.max(0, Math.min(2, Math.floor(terrain)));

      for (let y = 0; y <= top; y += 1) {
        put(
          x,
          y,
          bz,
          y === top ? ground.plinth : ground.pavement
        );
      }

      if (bz === outerZ && (x + variant) % 3 === 0) {
        put(x, 0, bz, ground.kerb);
      }
    }

    if ((x + variant * 2) % 4 === 0) {
      put(x, 0, restZ, ground.coping);
    }

    if ((x === 0 || x === W - 1) && variant % 2 === 1) {
      put(x, 0, innerZ, ground.revetment);
    }
  }

  for (let x = 0; x < W; x += 1) {
    const edge = Math.abs(x - midX) / midX;
    const uLimit = uBase - taperU * edge;
    const vLimit = vBase - taperV * edge;

    for (let y = 0; y < H; y += 1) {
      const dy = y - yc;

      for (let z = 0; z < D; z += 1) {
        const dz = z - zc;
        const u = sinA * dy + side * cosA * dz;
        const v = cosA * dy - side * sinA * dz;

        if (Math.abs(u) > uLimit || Math.abs(v) > vLimit) {
          continue;
        }

        const skin =
          uLimit - Math.abs(u) < 0.65 ||
          vLimit - Math.abs(v) < 0.55;

        const pattern = (x * 19 + y * 11 + z * 7 + variant * 13) % 37;
        const damaged =
          skin &&
          x > 1 &&
          x < W - 2 &&
          pattern < damageCuts &&
          (x + y + z + variant) % 4 !== 0;

        if (damaged) {
          continue;
        }

        let block = wood.planks;

        if (
          skin &&
          (x * 5 + y * 3 + z * 7 + texturePhase) % 13 === 0
        ) {
          block = wood.stripped;
        }

        put(x, y, z, block);
      }
    }
  }

  for (let x = 0; x < W; x += 1) {
    put(x, 1, restZ, wood.log);

    if ((x + variant) % 3 !== 1) {
      put(x, 2, restZ, wood.stripped);
    }
  }

  const bandRadius =
    variant === 2 || r8 > 0.82 ? 2 : 1;

  for (let x = 1; x < W - 1; x += 1) {
    for (let y = 6; y <= 7; y += 1) {
      for (let d = -bandRadius; d <= bandRadius; d += 1) {
        put(
          x,
          y,
          deckCenter + d,
          y === 7 ? wood.stripped : wood.planks
        );
      }
    }
  }

  const railCount = Math.min(
    4,
    2 + (variant === 2 ? 1 : 0) + (r9 > 0.55 ? 1 : 0)
  );

  for (let j = 0; j < railCount; j += 1) {
    const railV =
      railCount === 1
        ? 0
        : -1.05 + (2.1 * j) / (railCount - 1);

    for (let x = 2; x <= W - 3; x += 1) {
      const p = hullPoint(x, 3.0, railV);
      const gap =
        (x * 7 + j * 11 + variant * 3) % 19 === 0 &&
        r7 > 0.25;

      if (!gap) {
        put(p[0], p[1], p[2], wood.stripped);
      }
    }
  }

  if (variant !== 3 || r8 < 0.4) {
    for (let x = 2; x <= W - 3; x += 1) {
      if ((x + variant + Math.floor(r7 * 4)) % 17 === 0) {
        continue;
      }

      const p = hullPoint(x, -2.75, 0);
      put(p[0], p[1], p[2], wood.stripped);
    }
  }

  const ribXs = [2, 5, 8, 11, 14];

  for (let i = 0; i < ribXs.length; i += 1) {
    const skipRib =
      (i + variant + (r7 > 0.5 ? 1 : 0)) % 5 === 2;

    if (skipRib) {
      continue;
    }

    const x = ribXs[i];
    const core = hullPoint(x, 0, 0);
    const a = hullPoint(x, 2.9, -1.0);
    const b = hullPoint(x, 2.9, 1.0);

    stairLine(core, a, wood.stripped);
    stairLine(core, b, wood.stripped);
  }

  const keelRibXs = [1, 4, 7, 10, 13, 15];

  for (let i = 0; i < keelRibXs.length; i += 1) {
    const x = keelRibXs[i];

    stairLine(
      hullPoint(x, 1.8, 0),
      [x, 6, keelIn],
      wood.stripped
    );
  }

  for (let x = 0; x < W; x += 1) {
    put(x, 6, keelIn, wood.stripped);
    put(x, 6, keelBody, wood.log);
    put(x, 6, keelTip, wood.log);

    const keelFace =
      (x + variant + Math.floor(r9 * 4)) % 6 === 2
        ? wood.stripped
        : wood.log;

    put(x, 5, keelTip, keelFace);

    if (
      x > 0 &&
      x < W - 1 &&
      (x + variant + Math.floor(r8 * 3)) % 5 !== 1
    ) {
      put(x, 7, keelTip, wood.log);
    }
  }

  const shoreSlots = [2, 5, 8, 11, 14];
  const shoreCount =
    3 + ((variant + Math.floor(r6 * 3)) % 3);
  const shoreStart =
    (variant + Math.floor(r8 * shoreSlots.length)) %
    shoreSlots.length;

  for (let i = 0; i < shoreCount; i += 1) {
    const x = shoreSlots[(shoreStart + i) % shoreSlots.length];

    put(x, 0, innerZ, ground.coping);
    put(x, 1, innerZ, ground.kerb);

    const target = hullPoint(
      x,
      i % 2 === 0 ? 0.35 : -0.35,
      0
    );

    stairLine(
      [x, 0, restZ],
      target,
      wood.log
    );

    if ((i + variant + Math.floor(r7 * 2)) % 2 === 0) {
      stairLine(
        [x, 0, outerZ],
        [x, 2, restZ],
        wood.stripped
      );
    }
  }

  const sternTop =
    6 + ((variant + Math.floor(r4 * 2)) % 2);
  const sternRailY = Math.min(H - 1, sternTop + 1);

  for (let x = 12; x <= 15 && x < W; x += 1) {
    for (let y = 6; y <= sternTop; y += 1) {
      for (let d = -1; d <= 1; d += 1) {
        put(
          x,
          y,
          deckCenter + d,
          y === sternTop ? wood.stripped : wood.planks
        );
      }
    }
  }

  for (let x = 12; x <= 15 && x < W; x += 1) {
    put(x, sternRailY, deckCenter - 1, rigBlock);

    if ((x + variant) % 3 !== 0) {
      put(x, sternRailY, deckCenter + 1, rigBlock);
    }
  }

  stairLine(
    [W - 2, 5, deckCenter],
    [W - 1, sternRailY, deckCenter],
    wood.log
  );

  if (variant === 0 || variant === 2) {
    const flagY = Math.min(H - 1, sternRailY + 1);

    if (flagY > sternRailY) {
      stairLine(
        [W - 1, sternRailY, deckCenter],
        [W - 1, flagY, deckCenter],
        wood.log
      );
    }
  }

  const bowCore = hullPoint(0, 0, 0);
  const bowHigh = [
    1,
    6,
    clampInt(bowCore[2] + side, 1, D - 2)
  ];

  stairLine(bowCore, bowHigh, wood.log);

  stairLine(
    [0, 5, bowCore[2]],
    [2, 6, bowCore[2]],
    rigBlock
  );

  const mastX =
    5 + ((variant * 2 + Math.floor(r8 * 5)) % 7);
  const mastBase = hullPoint(mastX, 0, 0);

  const mastTopY =
    8 + ((variant + (r9 > 0.52 ? 1 : 0)) % 2);
  const mastLean = [-1, 0, 1, -1][variant];
  const mastRake = [0, 1, -1, 0][variant];

  const mastTop = [
    clampInt(mastX + mastLean, 1, W - 2),
    mastTopY,
    clampInt(mastBase[2] + mastRake, 1, D - 2)
  ];

  stairLine(mastBase, mastTop, wood.log);

  const yardY = Math.max(6, mastTopY - 2);
  const yardHalf =
    3 + ((variant + Math.floor(r8 * 2)) % 2);
  const yardX0 = Math.max(1, mastTop[0] - yardHalf);
  const yardX1 = Math.min(W - 2, mastTop[0] + yardHalf);

  stairLine(
    [mastTop[0], yardY, mastTop[2]],
    mastTop,
    wood.log
  );

  stairLine(
    [yardX0, yardY, mastTop[2]],
    [yardX1, yardY, mastTop[2]],
    wood.log
  );

  const hasMizzen =
    variant !== 1 || r9 > 0.7;

  let mizzenTopY = 0;
  let mizzenTopZ = 0;

  if (hasMizzen) {
    const mizzenBase = hullPoint(13, 0.15, 0);
    mizzenTopY = 7 + (variant === 3 ? 1 : 0);
    mizzenTopZ = clampInt(
      mizzenBase[2] - side,
      1,
      D - 2
    );

    const mizzenTop = [13, mizzenTopY, mizzenTopZ];

    stairLine(mizzenBase, mizzenTop, wood.log);

    const mizzenY = Math.max(6, mizzenTopY - 2);

    stairLine(
      [13, mizzenY, mizzenTopZ],
      mizzenTop,
      wood.log
    );

    stairLine(
      [11, mizzenY, mizzenTopZ],
      [15, mizzenY, mizzenTopZ],
      wood.stripped
    );
  }

  const topRig = [
    mastTop[0],
    Math.max(5, mastTopY - 1),
    mastTop[2]
  ];

  const yardRig = [
    mastTop[0],
    yardY,
    mastTop[2]
  ];

  rigTo(topRig, hullPoint(1, -2.2, 0));
  rigTo(topRig, hullPoint(15, -2.2, 0));
  rigTo(yardRig, hullPoint(1, 2.2, 0));

  if (variant !== 3 || r9 > 0.25) {
    rigTo(yardRig, hullPoint(15, 2.2, 0));
  }

  if (hasMizzen) {
    rigTo(
      [13, Math.max(5, mizzenTopY - 1), mizzenTopZ],
      hullPoint(12, -1.8, 0)
    );
  }

  for (let i = 0; i < voxels.length; i += 1) {
    const voxel = voxels[i];
    api.set(voxel[0], voxel[1], voxel[2], voxel[3]);
  }

  const centerX = Math.floor(midX);

  return {
    name: "Careened Pirate Ship",
    seatY: 0,
    anchors: {
      bow: [bowCore[0], bowCore[1], bowCore[2]],
      keel: [centerX, 6, keelTip],
      mast: [mastBase[0], mastBase[1], mastBase[2]],
      workside: [centerX, 0, restZ]
    }
  };
}

