export const envelope = [25, 18, 25];

export default function build(api) {
  const ground = api.theme.ground;
  const stone = api.theme.stone;
  const wall = api.theme.wall;
  const roof = api.theme.roof;

  const pavement = ground.pavement;
  const plinth = ground.plinth;
  const revetment = ground.revetment;
  const coping = ground.coping;

  const stonePrimary = stone.primary;
  const stoneAccent = stone.accent;

  const wallCore = wall.core;
  const wallWalk = wall.walk;
  const wallParapet = wall.parapet;
  const wallMerlon = wall.merlon;
  const wallTower = wall.tower;

  const roofSolid = roof.solid;
  const crystal = "minecraft:amethyst_block";

  function box(x0, x1, y0, y1, z0, z1, block) {
    for (let y = y0; y <= y1; y += 1) {
      for (let z = z0; z <= z1; z += 1) {
        for (let x = x0; x <= x1; x += 1) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  function ellipsoid(cx, cy, cz, rx, ry, rz, block) {
    const x0 = Math.floor(cx - rx);
    const x1 = Math.ceil(cx + rx);
    const y0 = Math.floor(cy - ry);
    const y1 = Math.ceil(cy + ry);
    const z0 = Math.floor(cz - rz);
    const z1 = Math.ceil(cz + rz);

    for (let y = y0; y <= y1; y += 1) {
      for (let z = z0; z <= z1; z += 1) {
        for (let x = x0; x <= x1; x += 1) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            api.set(x, y, z, block);
          }
        }
      }
    }
  }

  function ringLayer(y, block) {
    for (let x = 2; x <= 22; x += 1) {
      if (x < 10 || x > 14) {
        api.set(x, y, 2, block);
      }
      api.set(x, y, 22, block);
    }

    for (let z = 3; z <= 21; z += 1) {
      api.set(2, y, z, block);
      api.set(22, y, z, block);
    }
  }

  const seat = 3;

  // A shallow sunk foundation follows the sampled terrain. The open stair
  // run at the south side is kept continuous through the foundation.
  for (let x = 1; x <= 23; x += 1) {
    for (let z = 1; z <= 23; z += 1) {
      const terrain = api.heightAt(x, z);
      const entryColumn = z <= 2 && x >= 10 && x <= 14;
      const top = z === 1 && entryColumn ? 1 : 2;
      const groundY = Math.floor(seat + terrain);
      const start = entryColumn
        ? 0
        : Math.max(0, Math.min(top, groundY));

      for (let y = start; y <= top; y += 1) {
        const block =
          y === 0
            ? (terrain < -0.5 ? revetment : plinth)
            : stonePrimary;
        api.set(x, y, z, block);
      }
    }
  }

  // Landing stones outside the entrance make a climbable one-block stair.
  for (let x = 10; x <= 14; x += 1) {
    const terrain = api.heightAt(x, 0);
    api.set(x, 0, 0, terrain < -0.5 ? revetment : plinth);
  }

  // Court floor and a restrained cross-shaped devotional path.
  box(3, 21, 3, 3, 3, 21, pavement);

  for (let z = 3; z <= 8; z += 1) {
    api.set(12, 3, z, coping);
  }
  for (let x = 5; x <= 19; x += 1) {
    api.set(x, 3, 8, coping);
  }

  // Three-course curtain wall, open at the south gate.
  ringLayer(3, wallCore);
  ringLayer(4, wallWalk);
  ringLayer(5, wallParapet);

  for (let x = 3; x <= 21; x += 4) {
    if (x < 10 || x > 14) {
      api.set(x, 6, 2, wallMerlon);
    }
    api.set(x, 6, 22, wallMerlon);
  }

  for (let z = 4; z <= 20; z += 4) {
    api.set(2, 6, z, wallMerlon);
    api.set(22, 6, z, wallMerlon);
  }

  // Clear arched entrance.
  box(7, 8, 3, 6, 2, 3, wallTower);
  box(16, 17, 3, 6, 2, 3, wallTower);
  box(7, 17, 7, 7, 2, 3, roofSolid);

  // Four small corner towers with crystal finials.
  const cornerPositions = [
    [3, 3],
    [21, 3],
    [3, 21],
    [21, 21]
  ];

  for (let i = 0; i < cornerPositions.length; i += 1) {
    const cx = cornerPositions[i][0];
    const cz = cornerPositions[i][1];

    box(cx - 1, cx, 4, 8, cz - 1, cz, wallTower);
    box(cx - 1, cx, 9, 9, cz - 1, cz, coping);
    api.set(cx, 10, cz, crystal);
  }

  // Four low devotional lantern plinths leave the court open and traversable.
  const markerPositions = [
    [5, 6],
    [19, 6],
    [5, 16],
    [19, 16]
  ];

  for (let i = 0; i < markerPositions.length; i += 1) {
    const px = markerPositions[i][0];
    const pz = markerPositions[i][1];

    box(px - 1, px + 1, 4, 5, pz - 1, pz + 1, stonePrimary);
    api.set(px, 6, pz, crystal);
  }

  // Rear open-air shrine terrace and solid icon wall.
  box(6, 18, 4, 4, 17, 21, plinth);
  box(7, 17, 5, 5, 18, 21, stonePrimary);
  box(7, 17, 6, 6, 19, 21, stonePrimary);

  box(10, 14, 6, 6, 18, 19, stoneAccent);
  box(11, 13, 7, 7, 18, 19, stonePrimary);
  api.set(12, 8, 18, crystal);

  box(8, 16, 7, 10, 20, 21, wallCore);
  box(7, 8, 7, 10, 19, 21, wallTower);
  box(16, 17, 7, 10, 19, 21, wallTower);

  // A simple sacred emblem on the front of the icon wall.
  box(10, 14, 8, 8, 19, 19, stoneAccent);
  box(11, 13, 9, 9, 19, 19, stoneAccent);
  api.set(12, 10, 19, crystal);

  // Stepped gable and a single crystal finial.
  box(7, 17, 11, 11, 20, 21, roofSolid);
  box(8, 16, 12, 12, 20, 21, roofSolid);
  box(9, 15, 13, 13, 20, 21, roofSolid);
  box(10, 14, 14, 14, 20, 21, roofSolid);
  box(11, 13, 15, 15, 20, 21, roofSolid);
  api.set(12, 16, 20, crystal);

  // Tiered statue plinth.
  box(7, 12, 4, 4, 9, 14, plinth);
  box(8, 11, 5, 5, 10, 14, stonePrimary);
  box(9, 11, 6, 6, 10, 14, coping);

  // Rounded horizontal torso.
  ellipsoid(11.5, 9.5, 12, 4.0, 2.3, 2.6, stonePrimary);
  box(9, 12, 7, 8, 11, 13, stonePrimary);
  box(8, 13, 8, 10, 10, 14, stonePrimary);
  box(9, 14, 9, 11, 11, 13, stonePrimary);

  // Two grounded hind legs and hooves.
  box(8, 9, 6, 8, 10, 11, stonePrimary);
  box(10, 11, 6, 8, 13, 14, stonePrimary);
  box(8, 9, 6, 6, 10, 11, stoneAccent);
  box(10, 11, 6, 6, 13, 14, stoneAccent);

  // Rising curved neck, head, and muzzle facing east.
  box(13, 15, 10, 12, 10, 14, stonePrimary);
  box(13, 14, 11, 13, 11, 13, stonePrimary);
  box(14, 15, 12, 14, 10, 13, stonePrimary);
  box(15, 16, 13, 15, 10, 12, stonePrimary);

  box(15, 17, 14, 15, 10, 13, stonePrimary);
  box(17, 18, 13, 14, 10, 12, stonePrimary);
  api.set(18, 13, 11, stoneAccent);

  // Raised forelegs, bent forward in a rearing pose.
  box(14, 15, 10, 12, 10, 11, stonePrimary);
  box(15, 17, 10, 11, 10, 11, stonePrimary);
  box(17, 18, 9, 10, 10, 11, stoneAccent);

  box(14, 15, 11, 13, 13, 14, stonePrimary);
  box(15, 17, 11, 12, 13, 14, stonePrimary);
  box(17, 18, 10, 11, 13, 14, stoneAccent);

  // Mane, eye, nostril, and pointed ears on the visible side.
  box(13, 14, 11, 13, 9, 9, stoneAccent);
  box(14, 15, 13, 15, 9, 9, stoneAccent);
  api.set(15, 15, 9, stoneAccent);

  api.set(16, 14, 9, crystal);
  api.set(17, 13, 9, stoneAccent);

  api.set(15, 16, 10, stoneAccent);
  api.set(16, 16, 12, stoneAccent);

  // Angled crystal horn.
  api.set(17, 16, 11, stoneAccent);
  api.set(18, 16, 11, stoneAccent);
  api.set(18, 17, 11, crystal);
  api.set(19, 17, 11, crystal);

  // Flowing tail sweeping back toward the west.
  box(7, 9, 8, 10, 11, 13, stoneAccent);
  box(6, 8, 9, 11, 11, 13, stoneAccent);
  box(5, 7, 10, 11, 11, 13, stoneAccent);
  box(4, 6, 11, 12, 11, 13, stoneAccent);

  return {
    name: "Unicorn Sanctuary",
    seatY: 3,
    anchors: {
      door: [12, 3, 2]
    }
  };
}
